// CSD_RATIONALE_BEGIN
// This strategy generates free-form reasoning text, then transitions to arithmetic expressions enclosed in << >>.
// It uses raw logit manipulation to prevent premature closure of expressions by penalizing >> when expressions are short.
// The strategy switches to constrained mode when it encounters "<<", ensuring that valid arithmetic expressions are produced.
// It also checks for grammar dead-ends to avoid getting stuck in invalid states.
// CSD_RATIONALE_END

generated := [];
var steps := 0;
var insideConstrained := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  invariant insideConstrained ==> forall t: Token ::
    t in parser.ValidNextTokens(currentConstrained) ==> t in lm.Tokens
  invariant helpers.cost == steps
  decreases maxSteps - steps
{
  if !insideConstrained {
    // UNCONSTRAINED PHASE: generate reasoning text
    lm.GenerateLogits(prompt + generated);

    // Optionally penalize << early to force longer reasoning
    var exprCount := CSDHelpers.CountSubstring(helpers.PrefixToString(generated), "<<");
    if exprCount == 0 && steps < 15 {
      helpers.PenalizeTokenLogits(lm, ["<<"], 8.0);
    }

    var next := lm.ChooseNextTokenUnconstrained();
    helpers.cost := helpers.cost + 1;

    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;

    // Detect << to enter constrained mode
    if helpers.Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
  } else {
    // CONSTRAINED PHASE: grammar-enforced expression generation

    // Dead-end detection: bail if grammar too narrow
    var narrow := helpers.DeadEndDetection(parser, currentConstrained, 3);
    if narrow || parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      // RAW PATTERN: GenerateLogits → manipulate → ChooseNextToken → manual cost
      lm.GenerateLogits(prompt + generated);

      // Penalize >> when expression is short (< 5 tokens)
      if |currentConstrained| < 5 && ">>" in lm.Tokens {
        helpers.PenalizeTokenLogits(lm, [">>"], 3.0);
      }

      helpers.BoostTokenLogits(lm, parser.ValidNextTokens(currentConstrained), 5.0);

      var next := lm.ChooseNextToken();
      helpers.cost := helpers.cost + 1;
      generated := generated + [next];
      steps := steps + 1;

      if parser.IsValidPrefix(currentConstrained + [next]) {
        currentConstrained := currentConstrained + [next];
        if helpers.Contains(next, ">>") {
          insideConstrained := false;
        }
      } else {
        // Soft constraint allowed invalid token — abandon window
        insideConstrained := false;
      }
    }
  }
}

