      var validTokens := parser.ValidNextTokens(currentConstrained);
      helpers.BoostTokenLogits(lm, validTokens, 5.0);

      var next := lm.ChooseNextToken();
      helpers.cost := helpers.cost + 1;
      generated := generated + [next];
      steps := steps + 1;

      if parser.IsValidPrefix(currentConstrained + [next]) {
        currentConstrained := currentConstrained + [next];
        if helpers.Contains(next, ">>") {
          insideConstrained := false;
        }
      } else {
        // Soft constraint allowed invalid token — abandon window
        insideConstrained := false;
      }
    }
  }
}

cost := helpers.cost;
